    /// Count items of one shape anywhere in a scene tree, looking through the
    /// nesting wrappers (`When` / `Stack` / `Row` / `Column` / `Grid`) — a
    /// scene that parks its body behind a size gate still carries the items.
    fn count_items(items: &[SceneItem], pred: &dyn Fn(&SceneItem) -> bool) -> usize {
        items
            .iter()
            .map(|i| {
                let here = usize::from(pred(i));
                let kids: &[SceneItem] = match i {
                    SceneItem::When { items, .. }
                    | SceneItem::Stack { items, .. }
                    | SceneItem::Row { items, .. }
                    | SceneItem::Column { items, .. } => items,
                    _ => &[],
                };
                here + count_items(kids, pred)
            })
            .sum()
    }

