    #[test]
    fn compositor_tiles_land_on_the_drawer_geometry() {
        // parity guard: the committed scene must reproduce the Rust drawer's
        // numbers, because the click dispatch in input.rs keys off exactly
        // these regions. 240×140 card (the header, three tiles, shot row).
        let path = crate::vars::card_scene_path("compositor");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene = parse_scene_ron(&s).expect("compositor.ron parses");
        let p = pal();
        let mut m = SceneValues::new();
        m.insert("comp_meta", SceneValue::Text("1 on".into()));
        for (i, on) in [true, false, false].into_iter().enumerate() {
            m.insert_color(format!("comp_tile_{i}"), SceneColor::Raw(0x11223344));
            m.insert_color(
                format!("comp_dot_{i}"),
                SceneColor::Raw(if on { p.acc } else { crate::ui::fg3(&p) }),
            );
            m.insert_color(
                format!("comp_ink_{i}"),
                SceneColor::Raw(if on { p.acc } else { p.fg }),
            );
            m.insert(
                format!("comp_state_{i}"),
                SceneValue::Text(if on { "on".into() } else { "off".into() }),
            );
            m.insert_color(format!("comp_shot_{i}"), SceneColor::Raw(0));
        }
        let (w, h) = (240.0, 140.0);
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(&mut v, 0.0, 0.0, w, h, scale(), &p, &m, 0, true, true);

        // drawer: tiles at y = 24 (hdr) + 6, 40 px tall, r 7; tw = (w − 24 − 16) / 3
        let tw = (w - 24.0 - 16.0) / 3.0;
        let mut keys: Vec<u32> = hits.iter().map(|t| t.key).collect();
        keys.sort_unstable();
        assert_eq!(
            keys,
            vec![
                crate::shell::COMP_BLUR_KEY,
                crate::shell::COMP_SHADOW_KEY,
                crate::shell::COMP_OPACITY_KEY,
                crate::shell::COMP_SHOT_AREA_KEY,
                crate::shell::COMP_SHOT_FULL_KEY,
            ],
            "every drawer key is still reachable, in any order"
        );
        for (i, k) in [
            crate::shell::COMP_BLUR_KEY,
            crate::shell::COMP_SHADOW_KEY,
            crate::shell::COMP_OPACITY_KEY,
        ]
        .into_iter()
        .enumerate()
        {
            let t = hits
                .iter()
                .find(|t| t.key == k)
                .expect("effect tile region");
            assert_eq!(t.y, 30.0, "effect row sits 30 px down (header 24 + 6)");
            assert_eq!(t.h, 40.0, "40 px tiles");
            assert!(
                (t.x - (12.0 + i as f32 * (tw + 8.0))).abs() < 0.01,
                "tile {i} x"
            );
            assert!((t.w - tw).abs() < 0.01, "tile {i} width (equal thirds)");
        }
        // the state dots: 5×5 at r 2.5, centered on the tile, 7 px down
        let dots: Vec<&Cmd> = v
            .iter()
            .filter(|c| matches!(c, Cmd::Rect { w, r, .. } if (*w - 5.0).abs() < 0.01 && (*r - 2.5).abs() < 0.01))
            .collect();
        assert_eq!(dots.len(), 3, "one state dot per effect tile");
        if let Cmd::Rect { x, y, .. } = dots[0] {
            assert!((*y - 37.0).abs() < 0.01, "dot 7 px below the tile top");
            assert!(
                (*x - (12.0 + tw / 2.0 - 2.5)).abs() < 0.01,
                "dot centered on its tile"
            );
        }
        // the tile rows: label at +17, on/off caption at +29 (fg3), both
        // centered on the tile — a centered `Text` in a container gets the
        // container's width from the fill pass, so `center: true` alone lands
        // it on the tile center (`center_x` would push it a half-width right)
        for (i, (want_y, want_text)) in [
            (47.0, "Blur"),
            (59.0, "on"),
            (47.0, "Shadow"),
            (59.0, "off"),
        ]
        .into_iter()
        .enumerate()
        {
            assert!(
                v.iter().any(|c| matches!(c, Cmd::Text { x, y, text, .. }
                    if (*y - want_y).abs() < 0.01
                        && *text == want_text
                        && (*x - (12.0 + (i / 2) as f32 * (tw + 8.0) + tw / 2.0)).abs() < 0.01)),
                "`{want_text}` at y={want_y}, centered on its tile"
            );
        }
        // the screenshot row: y = 30 + 40 + 8, two half-width buttons 30 px tall
        let sw = (w - 24.0 - 8.0) / 2.0;
        for (i, k) in [
            crate::shell::COMP_SHOT_AREA_KEY,
            crate::shell::COMP_SHOT_FULL_KEY,
        ]
        .into_iter()
        .enumerate()
        {
            let t = hits.iter().find(|t| t.key == k).expect("screenshot region");
            assert_eq!(t.y, 78.0, "shot row below the tiles");
            assert_eq!(t.h, 30.0, "30 px buttons");
            assert!(
                (t.x - (12.0 + i as f32 * (sw + 8.0))).abs() < 0.01,
                "shot {i} x"
            );
            assert!((t.w - sw).abs() < 0.01, "shot {i} width");
        }
        // the icon/label pair straddles each button's center (glyph at −30, text at +2)
        let shot_glyph = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text { x, y, text, .. } if text == crate::icons::ICON_SELECT => Some((*x, *y)),
                _ => None,
            })
            .expect("the area-shot glyph draws");
        assert!(
            (shot_glyph.1 - 86.0).abs() < 0.01,
            "glyph 8 px below the button top"
        );
        assert!(
            (shot_glyph.0 - (12.0 + sw / 2.0 - 30.0)).abs() < 0.01,
            "glyph 30 px left of the button center"
        );
    }

    #[test]
    fn compositor_shot_row_stands_down_on_a_short_card() {
        // 100 px card: the tiles still draw, the screenshot row does not
        let path = crate::vars::card_scene_path("compositor");
        if !path.exists() {
            return;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        let scene: CardScene = parse_scene_ron(&s).expect("compositor.ron parses");
        let mut m = SceneValues::new();
        m.insert("comp_meta", SceneValue::Text("0 on".into()));
        for i in 0..3 {
            m.insert(format!("comp_state_{i}"), SceneValue::Text("off".into()));
            m.insert_color(format!("comp_tile_{i}"), SceneColor::Raw(0));
            m.insert_color(format!("comp_shot_{i}"), SceneColor::Raw(0));
        }
        let (hits, _) = scene.draw(
            &mut Vec::new(),
            0.0,
            0.0,
            240.0,
            100.0,
            scale(),
            &pal(),
            &m,
            0,
            true,
            true,
        );
        let keys: Vec<u32> = hits.iter().map(|t| t.key).collect();
        assert!(
            keys.contains(&crate::shell::COMP_BLUR_KEY),
            "the effect tiles survive"
        );
        assert!(
            !keys.contains(&crate::shell::COMP_SHOT_AREA_KEY)
                && !keys.contains(&crate::shell::COMP_SHOT_FULL_KEY),
            "a 100 px card has no room for the screenshot row"
        );
    }

    // ── power cards (powerh / powerv), 2026-09-25 ──

    /// the bindings a power scene needs: five buttons, one held at `fill`
    /// (a 0..1 fraction, painted once the shell's own 1.5 px sliver threshold
    /// clears), the shared liquid ink and a `clear` track.
    fn power_vals(holding: usize, fill: f32) -> SceneValues {
        let p = pal();
        let mut m = SceneValues::new();
        m.insert_color("clear", SceneColor::Raw(0));
        m.insert_color(
            "power_hold_fill",
            SceneColor::Raw(crate::ui::mix(crate::ui::hover(&p), p.acc, 0.5)),
        );
        for i in 0..5 {
            m.insert_color(
                format!("power_bg_{i}"),
                SceneColor::Raw(if i == holding {
                    crate::ui::acc_tint(&p)
                } else {
                    crate::ui::raised(&p)
                }),
            );
            m.insert(
                format!("power_hold_{i}"),
                SceneValue::Text(if i == holding {
                    format!("{fill:.4}")
                } else {
                    "0.0000".into()
                }),
            );
            m.insert(
                format!("power_hold_on_{i}"),
                SceneValue::Toggle(i == holding && 32.0 * fill >= 1.5),
            );
            m.insert_color(
                format!("power_ink_{i}"),
                SceneColor::Raw(if matches!(i, 1 | 3 | 4) {
                    crate::ui::mix(crate::ui::DANGER, p.fg, 0.25)
                } else {
                    p.fg
                }),
            );
        }
        m
    }

    /// parse a committed power card scene, or `None` when the file is absent
    /// (the live config tree is the source of truth).
    fn power_scene(id: &str) -> Option<CardScene> {
        let path = crate::vars::card_scene_path(id);
        if !path.exists() {
            return None;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        Some(parse_scene_ron(&s).unwrap_or_else(|e| panic!("{id}.ron must parse: {e}")))
    }

    #[test]
    fn power_scenes_parse_zero_ink_with_five_hit_buttons() {
        for id in ["powerh", "powerv"] {
            let Some(scene) = power_scene(id) else { return };
            assert!(
                scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Header { .. })),
                "{id} scene declares Header chrome"
            );
            assert!(
                !scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ink { .. })),
                "{id} scene is fully declarative (no Ink body)"
            );
            fn keys_in(items: &[SceneItem], out: &mut Vec<u32>) {
                for i in items {
                    match i {
                        SceneItem::Hit { key, .. } => out.push(key.constant() as u32),
                        SceneItem::Row { items, .. }
                        | SceneItem::Column { items, .. }
                        | SceneItem::Stack { items, .. } => keys_in(items, out),
                        _ => {}
                    }
                }
            }
            let mut keys: Vec<u32> = Vec::new();
            keys_in(&scene.items, &mut keys);
            keys.sort_unstable();
            assert_eq!(
                keys,
                (0..5)
                    .map(|i| crate::shell::POWER_CARD_KEY_BASE + i)
                    .collect::<Vec<_>>(),
                "{id} scene keeps every power button key (12000..12004), in order"
            );
        }
    }

    #[test]
    fn power_buttons_land_on_the_drawer_geometry() {
        // parity guard: input.rs dispatches hold-to-confirm off exactly these
        // regions. 240x140 card, five 32 px buttons, 9 px gaps, 30 px header.
        let Some(scene) = power_scene("powerh") else {
            return;
        };
        let (w, h) = (240.0, 140.0);
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            w,
            h,
            scale(),
            &pal(),
            &power_vals(usize::MAX, 0.0),
            0,
            true,
            true,
        );

        // drawer: cx0 = x + (w − 5·32 − 4·9) / 2 + 16, cy = y + 30 + (110−32)/2 + 16
        let total = 5.0 * 32.0 + 4.0 * 9.0;
        let bx0 = (w - total) / 2.0;
        let by = 30.0 + (110.0 - 32.0) / 2.0;
        for (i, t) in hits.iter().enumerate() {
            assert_eq!(
                t.key,
                crate::shell::POWER_CARD_KEY_BASE + i as u32,
                "button {i} key"
            );
            assert!(
                (t.x - (bx0 + i as f32 * 41.0)).abs() < 0.01,
                "button {i} x (centered block)"
            );
            assert!(
                (t.w - 32.0).abs() < 0.01 && (t.h - 32.0).abs() < 0.01,
                "button {i} is 32x32"
            );
            assert!(
                (t.y - by).abs() < 0.01,
                "button {i} centered in the body below the header"
            );
        }
        // each button paints its background + hairline and its glyph
        let fills = v
            .iter()
            .filter(|c| matches!(c, Cmd::Rect { w, h, r, .. } if (*w - 32.0).abs() < 0.01 && (*h - 32.0).abs() < 0.01 && (*r - 10.0).abs() < 0.01))
            .count();
        assert_eq!(fills, 5, "one 32 px r-10 background per button");
        assert_eq!(
            v.iter()
                .filter(|c| matches!(c, Cmd::Outline { w, .. } if (*w - 32.0).abs() < 0.01))
                .count(),
            5,
            "one hairline outline per button"
        );
        for (i, glyph) in ["\u{f023}", "\u{f08b}", "\u{f186}", "\u{f021}", "\u{f011}"]
            .into_iter()
            .enumerate()
        {
            assert!(
                v.iter().any(
                    |c| matches!(c, Cmd::Text { x, y, text, size, center: true, .. }
                    if text == glyph
                        && (*size - 14.0).abs() < 0.01
                        && (*y - (by + 16.0)).abs() < 0.01
                        && (*x - (bx0 + i as f32 * 41.0 + 16.0)).abs() < 0.01)
                ),
                "button {i} glyph centered on its box, 14 px"
            );
        }
        // at rest: no hold liquid anywhere (the gate is closed and the
        // fraction is zero)
        assert!(
            !v.iter()
                .any(|c| matches!(c, Cmd::Rect { w, .. } if (*w - 28.0).abs() < 0.01)),
            "no hold liquid at rest"
        );
    }

    #[test]
    fn power_hold_fills_the_button_bottom_up() {
        // holding button 2 at half progress: the liquid is 28 px wide, 16 px
        // tall, and its bottom edge sits 2 px above the button's bottom (the
        // drawer's `x + 2, y + d − 2 − fh` geometry) with the accent mix ink
        let Some(scene) = power_scene("powerh") else {
            return;
        };
        let (w, h) = (240.0, 140.0);
        let bx0 = (w - (5.0 * 32.0 + 4.0 * 9.0)) / 2.0;
        let by = 30.0 + (110.0 - 32.0) / 2.0;
        let mut v: Vec<Cmd> = Vec::new();
        let (_, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            w,
            h,
            scale(),
            &pal(),
            &power_vals(2, 0.5),
            0,
            true,
            true,
        );
        // the liquid rides a transparent 28x32 track (the `clear` value) and
        // the fill is the shorter rect on top of it
        let track = v
            .iter()
            .find(|c| matches!(c, Cmd::Rect { w, h, .. } if (*w - 28.0).abs() < 0.01 && (*h - 32.0).abs() < 0.01))
            .expect("the held button paints its liquid track");
        if let Cmd::Rect { color, .. } = track {
            assert_eq!(
                *color, 0,
                "the track is fully transparent at rest (`clear`)"
            );
        }
        let liquid = v
            .iter()
            .find(|c| matches!(c, Cmd::Rect { w, h, .. } if (*w - 28.0).abs() < 0.01 && (*h - 16.0).abs() < 0.01))
            .expect("the held button paints its liquid");
        if let Cmd::Rect {
            x,
            y,
            w: lw,
            h: lh,
            color,
            ..
        } = liquid
        {
            assert!(
                (*lw - 28.0).abs() < 0.01 && (*lh - 16.0).abs() < 0.01,
                "half of the 32 px button"
            );
            assert!(
                (*x - (bx0 + 2.0 * 41.0 + 2.0)).abs() < 0.01,
                "liquid inset 2 px from the button's left edge"
            );
            assert!(
                (*y - (by + 14.0)).abs() < 0.01,
                "liquid bottom anchored 2 px above the button's bottom"
            );
            assert_eq!(
                *color,
                crate::ui::mix(crate::ui::hover(&pal()), pal().acc, 0.5),
                "accent-mixed liquid"
            );
        }
        assert_eq!(
            v.iter().filter(|c| matches!(c, Cmd::Rect { w, h, .. } if (*w - 28.0).abs() < 0.01 && (*h - 32.0).abs() < 0.01)).count(),
            1,
            "one liquid track, on the held button only"
        );
    }

    #[test]
    fn power_hold_stands_down_under_the_sliver_threshold() {
        // the shell only paints a hold once it covers 1.5 px: a fresh press
        // (fill 0.02 → 0.64 px) draws no liquid at all
        let Some(scene) = power_scene("powerh") else {
            return;
        };
        let mut v: Vec<Cmd> = Vec::new();
        let (_, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            240.0,
            140.0,
            scale(),
            &pal(),
            &power_vals(0, 0.02),
            0,
            true,
            true,
        );
        assert!(
            !v.iter()
                .any(|c| matches!(c, Cmd::Rect { w, .. } if (*w - 28.0).abs() < 0.01)),
            "a sub-1.5 px hold paints nothing"
        );
    }

    #[test]
    fn powerv_stacks_the_buttons_in_one_centered_column() {
        // the vertical card: 5 buttons on a 41 px pitch, the block centered
        // in the body below the header, each button centered in the width
        let Some(scene) = power_scene("powerv") else {
            return;
        };
        let (w, h) = (200.0, 260.0);
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            w,
            h,
            scale(),
            &pal(),
            &power_vals(usize::MAX, 0.0),
            0,
            true,
            true,
        );
        assert_eq!(hits.len(), 5, "five button regions");
        let stack_h = 5.0 * 32.0 + 4.0 * 9.0;
        let base = 30.0 + ((h - 30.0) - stack_h).max(0.0) / 2.0;
        for (i, t) in hits.iter().enumerate() {
            assert!(
                (t.x - (w / 2.0 - 16.0)).abs() < 0.01,
                "button {i} centered in the card width"
            );
            assert!(
                (t.y - (base + i as f32 * 41.0)).abs() < 0.01,
                "button {i} on the 41 px pitch"
            );
            assert!(
                (t.w - 32.0).abs() < 0.01 && (t.h - 32.0).abs() < 0.01,
                "button {i} is 32x32"
            );
        }
    }

    #[test]
    fn row_halign_centers_a_block_of_fixed_width_children() {
        // `halign: center` is a no-op for children that FILL the row (they
        // already span it) and centers the block when every child declares
        // its own width
        let filled = r#"(items: [
            Row(x: 0.0, y: 0.0, w: 100.0, h: 10.0, halign: center, items: [
                Text(x: 0.0, y: 0.0, w: 0.0, text: "a", font_size: 10.0),
                Text(x: 0.0, y: 0.0, w: 0.0, text: "b", font_size: 10.0),
            ]),
        ])"#;
        let s: CardScene = parse_scene_ron(filled).expect("filled fixture parses");
        let mut v: Vec<Cmd> = Vec::new();
        s.draw(
            &mut v,
            0.0,
            0.0,
            100.0,
            20.0,
            scale(),
            &pal(),
            &vals(),
            0,
            true,
            true,
        );
        let xs: Vec<f32> = v
            .iter()
            .filter_map(|c| match c {
                Cmd::Text { x, .. } => Some(*x),
                _ => None,
            })
            .collect();
        assert_eq!(
            xs,
            vec![0.0, 50.0],
            "fills stay left-anchored, split equally"
        );

        let fixed = r#"(items: [
            Row(x: 0.0, y: 0.0, w: 100.0, h: 10.0, spacing: 4.0, halign: center, items: [
                Surface(x: 0.0, y: 0.0, w: 20.0, h: 10.0, color: acc),
                Surface(x: 0.0, y: 0.0, w: 20.0, h: 10.0, color: acc),
            ]),
        ])"#;
        let s: CardScene = parse_scene_ron(fixed).expect("fixed fixture parses");
        let mut v: Vec<Cmd> = Vec::new();
        s.draw(
            &mut v,
            0.0,
            0.0,
            100.0,
            20.0,
            scale(),
            &pal(),
            &vals(),
            0,
            true,
            true,
        );
        let xs: Vec<f32> = v
            .iter()
            .filter_map(|c| match c {
                Cmd::Rect { x, .. } => Some(*x),
                _ => None,
            })
            .collect();
        assert_eq!(
            xs,
            vec![28.0, 52.0],
            "a 44 px block centers in 100 px (28 px lead)"
        );
    }

    #[test]
    fn bar_vertical_fills_bottom_up_and_surface_strokes_over() {
        // `vertical: true` scales the box height by the fraction, anchored on
        // the bottom edge; the horizontal bar is unchanged
        let vron = r#"(items: [
            Bar(x: 0.0, y: 0.0, w: 40.0, h: 20.0, vertical: true, value: "50", fill: acc, track: fg3),
            Bar(x: 50.0, y: 0.0, w: 40.0, h: 20.0, value: "50", fill: acc, track: fg3),
        ])"#;
        let s: CardScene = parse_scene_ron(vron).expect("bar fixture parses");
        let mut v: Vec<Cmd> = Vec::new();
        s.draw(
            &mut v,
            0.0,
            0.0,
            100.0,
            40.0,
            scale(),
            &pal(),
            &vals(),
            0,
            true,
            true,
        );
        let mut fills: Vec<(f32, f32, f32)> = Vec::new();
        for c in &v {
            if let Cmd::Rect { x, y, w, h, .. } = c {
                if (*h - 20.0).abs() > 0.01 || (*w - 40.0).abs() > 0.01 {
                    fills.push((*x, *y, *w));
                }
            }
        }
        assert_eq!(
            fills,
            vec![(0.0, 10.0, 40.0), (50.0, 0.0, 20.0)],
            "vertical fill: 20 x 0.5 anchored at y 10; horizontal: 40 x 0.5"
        );
        // `stroke` outlines the box on the fill's own rect
        let sron = r#"(items: [ Surface(x: 4.0, y: 6.0, w: 30.0, h: 18.0, r: 5.0, color: acc, stroke: 1.0, stroke_color: Some(hairline)) ])"#;
        let s: CardScene = parse_scene_ron(sron).expect("surface fixture parses");
        let mut v: Vec<Cmd> = Vec::new();
        s.draw(
            &mut v,
            0.0,
            0.0,
            100.0,
            40.0,
            scale(),
            &pal(),
            &vals(),
            0,
            true,
            true,
        );
        assert_eq!(v.len(), 2, "fill + outline");
        match v[1] {
            Cmd::Outline {
                x,
                y,
                w,
                h,
                r,
                color,
                ..
            } => {
                assert_eq!(
                    (x, y, w, h, r),
                    (4.0, 6.0, 30.0, 18.0, 5.0),
                    "outline traces the box"
                );
                assert_eq!(color, crate::ui::hairline(&pal()), "hairline ink");
            }
            _ => panic!("expected an Outline as the second command"),
        }
    }

    /// `batt_vals` mirrors the battery card's `scene_values` block: the live
    /// percent (as text for `batt_pct`, as ink for `batt_ink`), the AC bolt,
    /// the pane/hover gates and the two panes' contents.
    fn batt_vals(pct: i32, pane: usize, on_ac: bool, present: bool) -> SceneValues {
        let p = pal();
        let mut m = SceneValues::new();
        m.insert("batt_pct", SceneValue::Text(pct.to_string()));
        m.insert(
            "batt_pct_txt",
            SceneValue::Text(format!("{pct}%{}", if on_ac { " \u{f0e7}" } else { "" })),
        );
        m.insert_color("batt_ink", SceneColor::Raw(battery_level_color(&p, pct)));
        m.insert("batt_absent", SceneValue::Toggle(!present));
        m.insert("batt_h_pane", SceneValue::Ring(pane as f32));
        m.insert("batt_v_pane", SceneValue::Ring(pane as f32));
        m.insert("batt_h_pane_0", SceneValue::Toggle(present && pane == 0));
        m.insert("batt_h_pane_1", SceneValue::Toggle(present && pane == 1));
        m.insert("batt_v_pane_0", SceneValue::Toggle(present && pane == 0));
        m.insert("batt_v_pane_1", SceneValue::Toggle(present && pane == 1));
        m.insert("batt_h_hover", SceneValue::Toggle(present));
        m.insert("batt_v_hover", SceneValue::Toggle(present));
        m.insert_color("batt_psave_bg", SceneColor::Raw(crate::ui::raised(&p)));
        m.insert_color("batt_psave_ink", SceneColor::Raw(p.fg));
        m.insert(
            "batt_psave_lbl",
            SceneValue::Text(format!("{} Power save", crate::icons::ICON_BATTERY_SAVER)),
        );
        let row = |a: &str, b: String| SceneRow {
            cols: vec![a.into(), b],
            ..Default::default()
        };
        m.insert(
            "batt_info",
            SceneValue::Rows(vec![
                row(
                    "State",
                    if on_ac {
                        "Charging \u{26a1}".into()
                    } else {
                        "Discharging".into()
                    },
                ),
                row("Battery", format!("{pct}%")),
                row("Draw", "4.2 W".into()),
                row("Remaining", "3:20".into()),
            ]),
        );
        m
    }
    fn batt_scene(id: &str) -> Option<CardScene> {
        let path = crate::vars::card_scene_path(id);
        if !path.exists() {
            return None;
        }
        let s = std::fs::read_to_string(&path).expect("scene file readable");
        Some(parse_scene_ron(&s).unwrap_or_else(|e| panic!("{id}.ron must parse: {e}")))
    }
    /// Draw a battery scene into a 240x140 card at the origin and hand back
    /// the commands + regions.
    fn batt_draw(id: &str, pct: i32, pane: usize, present: bool) -> (Vec<Cmd>, Vec<SceneHit>) {
        let scene = batt_scene(id).expect("battery scene present");
        let mut v: Vec<Cmd> = Vec::new();
        let vals = batt_vals(pct, pane, false, present);
        // the drawers always paint the header chrome themselves
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            240.0,
            140.0,
            scale(),
            &pal(),
            &vals,
            0,
            true,
            true,
        );
        (v, hits)
    }
    /// The first `Outline` in a command list — the battery body stroke, the
    /// drawer's own `Cmd::Outline` around the icon.
    fn first_outline(v: &[Cmd]) -> (f32, f32, f32, f32) {
        v.iter()
            .find_map(|c| match c {
                Cmd::Outline { x, y, w, h, .. } => Some((*x, *y, *w, *h)),
                _ => None,
            })
            .expect("a battery body outline")
    }
    /// One comparable line per command — the differential-test fingerprint.
    /// Any command the pomodoro does not use still shows up by its variant
    /// index, so an unexpected extra command can never compare equal.
    fn fmt(v: &[Cmd]) -> Vec<String> {
        v.iter()
            .enumerate()
            .map(|(i, c)| match c {
                Cmd::Text {
                    x,
                    y,
                    right,
                    center,
                    text,
                    size,
                    color,
                    ..
                } => {
                    format!("T {x:.2} {y:.2} {right} {center} {size:.2} {color} {text}")
                }
                Cmd::Rect {
                    x,
                    y,
                    w,
                    h,
                    r,
                    color,
                } => format!("R {x:.2} {y:.2} {w:.2} {h:.2} {r:.2} {color}"),
                // Lines and images carry GEOMETRY the two painters compute
                // independently (a plot's box, a thumbnail's box), so compare
                // them in full — counting them would have let a 20 px plot
                // floor difference through.
                Cmd::Line {
                    x0,
                    y0,
                    x1,
                    y1,
                    w,
                    color,
                } => {
                    format!("L {x0:.2} {y0:.2} {x1:.2} {y1:.2} {w:.2} {color}")
                }
                Cmd::Image { x, y, w, h, key } => {
                    format!("I {x:.2} {y:.2} {w:.2} {h:.2} {key}")
                }
                // `Cmd` is neither `Debug` nor `Display`; the command's slot
                // plus a zero-width marker is enough to fail loudly on an
                // unexpected extra command.
                _ => format!("#{i} <other>"),
            })
            .collect()
    }

    /// (x, y, w, h, key) fingerprint of a hit list, at 2 dp.
    fn hits_fmt(h: &[SceneHit]) -> Vec<String> {
        h.iter()
            .map(|k| format!("H {:.2} {:.2} {:.2} {:.2} #{}", k.x, k.y, k.w, k.h, k.key))
            .collect()
    }

    fn auddev_shell(
        devices: &[(u32, &str, f32, bool)],
        sources: &[(u32, &str, f32, bool)],
        default: u32,
        hover: u32,
    ) -> crate::shell::Shell {
        let cfg: crate::config::Config =
            toml::from_str(crate::config::DEFAULT_SHELL_TOML).expect("default config parses");
        let mut s = crate::shell::Shell::new(cfg);
        s.scale = scale();
        s.sv_fg = pal().fg;
        s.sv_bg = pal().bg;
        s.sv_acc = pal().acc;
        s.sv_sfg = pal().sfg;
        s.audio_sinks = devices
            .iter()
            .map(|(i, n, v, m)| (*i, (*n).to_string(), *v, *m))
            .collect();
        s.audio_sources = sources
            .iter()
            .map(|(i, n, v, m)| (*i, (*n).to_string(), *v, *m))
            .collect();
        s.audio_default = default;
        s.hover_key = hover;
        s
    }

    #[test]
    fn audiodevice_scene_is_zero_ink() {
        let Some(scene) = batt_scene("audiodevice") else {
            return;
        };
        assert!(
            !scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Ink { .. })),
            "audiodevice is fully declarative (2026-09-27): the rows, their three
            cells and both per-row keys are declared, the Rust painter is fallback"
        );
        assert!(
            scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Header { .. })),
            "header chrome is declared"
        );
        let rows = scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Rows {
                    name,
                    key_stride,
                    aux,
                    cols,
                    bottom,
                    region_dy,
                    region_dh,
                    ..
                } = i
                {
                    Some((
                        name.clone(),
                        *key_stride,
                        aux.is_some(),
                        cols.len(),
                        *bottom,
                        *region_dy,
                        *region_dh,
                    ))
                } else {
                    None
                }
            })
            .expect("audiodevice scene declares the device Rows");
        assert_eq!(rows.0, "auddev_rows", "rows bind the auddev_rows value");
        assert_eq!(
            rows.1, 2,
            "every row answers to two adjacent keys (row / mute)"
        );
        assert!(rows.2, "the mute box is the row's second region");
        assert_eq!(rows.3, 3, "name, vol % and the mute glyph");
        assert_eq!(
            rows.4, 2.0,
            "rows stop at card_h - 2, the drawer's own break line"
        );
        assert_eq!(
            (rows.5, rows.6),
            (-2.0, 2.0),
            "the row regions overhang 2 px up and run 2 px tall"
        );
        // the char estimator is the drawer's, not the engine's average
        let SceneCol {
            truncate, trunc, ..
        } = &scene
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Rows { cols, .. } = i {
                    cols.first()
                } else {
                    None
                }
            })
            .expect("name column")
            .clone();
        assert_eq!(*truncate, Some(66.0), "name reserves the drawer's 66 px");
        let t = trunc
            .as_ref()
            .expect("name declares the drawer's char estimator");
        assert_eq!(
            (t.glyph_px, t.min_chars),
            (5.6, 4.0 as usize),
            "avail / 5.6 with a 4-char floor"
        );
    }

    #[test]
    fn the_audiodevice_scene_matches_its_own_drawer() {
        // Same idea as the pomodoro differential: one `Shell`, both painters.
        // Here it checks the row ladder too — the scene's hits must be the
        // drawer's `hover_regions`, in order, to the pixel.
        let devs = [
            (90u32, "USB-C Audio", 0.8f32, false),
            (92, "HDMI / DisplayPort 2.1", 1.0, false),
        ];
        let srcs = [(98u32, "Built-in Microphone", 0.4, true)];
        // resting, row 0 hovered, the mute box of row 0 hovered (the % must NOT
        // tint), and a source hovered
        for hover in [0u32, 31_920, 31_921, 31_924] {
            for (w, h) in [(220.0, 110.0), (260.0, 150.0), (200.0, 100.0)] {
                let mut s = auddev_shell(&devs, &srcs, 90, hover);
                let vals = s.scene_values();
                let mut rust: Vec<Cmd> = Vec::new();
                s.draw_audiodevice_card(&mut rust, 0.0, 0.0, w, h, &pal());
                let (scene_v, scene_hits) = gau_draw_hover("audiodevice", w, h, &vals, hover);
                assert_eq!(
                    fmt(&rust),
                    fmt(&scene_v),
                    "hover {hover}: the scene and the drawer must paint the same commands at {w}x{h}"
                );
                // Sorted by key: the engine registers a row's `aux` box BEFORE
                // the row's own region (so the karaoke early-`continue` cannot
                // drop it) while the drawer registers row-then-box. The two
                // never overlap — the row's region is clipped to the box's
                // left edge minus `aux.gap` — so resolution is identical and
                // only the registration order differs.
                let regions = s.hover_region_snapshot();
                let mut want = regions
                    .iter()
                    .map(|r| SceneHit {
                        x: r.0,
                        y: r.1,
                        w: r.2,
                        h: r.3,
                        key: r.4,
                        action: None,
                    })
                    .map(|k| format!("H {:.2} {:.2} {:.2} {:.2} #{}", k.x, k.y, k.w, k.h, k.key))
                    .collect::<Vec<_>>();
                let mut got = hits_fmt(&scene_hits);
                want.sort();
                got.sort();
                assert_eq!(
                    want, got,
                    "hover {hover}: the scene's hit boxes must be the drawer's regions at {w}x{h}"
                );
            }
        }
    }

    /// The power-draw trace, one `Shell` per case and both painters.
    fn powerdraw_shell(hist: &[(f32, f32)]) -> crate::shell::Shell {
        let cfg: crate::config::Config =
            toml::from_str(crate::config::DEFAULT_SHELL_TOML).expect("default config parses");
        let mut s = crate::shell::Shell::new(cfg);
        s.scale = scale();
        s.sv_fg = pal().fg;
        s.sv_bg = pal().bg;
        s.sv_acc = pal().acc;
        s.sv_sfg = pal().sfg;
        s.pw_history = hist.iter().copied().collect();
        s
    }

    #[test]
    fn the_powerdraw_scene_matches_its_own_drawer() {
        // the empty history (the drawer's own early return), a single sample
        // (the flat idle trace, not a trace), a rising pair, a falling pair
        // (no charging arrow), a long flat run, and a full 60-sample window
        // with both channels moving × 4 card boxes
        let hists: &[&[(f32, f32)]] = &[
            &[],
            &[(8.0, 35.0)],
            &[(8.0, 35.0), (8.4, 36.0)],
            &[(8.4, 36.0), (8.0, 35.0)],
            &[(4.0, 4.0), (4.0, 4.0), (4.0, 4.0), (4.0, 4.0)],
        ];
        let long: Vec<(f32, f32)> = (0..60)
            .map(|i| (4.0 + (i % 7) as f32 * 0.9, 20.0 + (i % 5) as f32 * 4.0))
            .collect();
        for hist in hists.iter().copied().chain([long.as_slice()]) {
            // the last box is narrower than the drawer's own `.max(20)` plot
            // floor bites at (card_w - 108 < 20), so the `min_w` floors have to
            // carry it
            for (w, h) in [
                (170.0, 110.0),
                (200.0, 120.0),
                (240.0, 160.0),
                (180.0, 100.0),
                (120.0, 90.0),
            ] {
                let mut s = powerdraw_shell(hist);
                let vals = s.scene_values();
                let mut rust: Vec<Cmd> = Vec::new();
                s.draw_powerdraw_card(&mut rust, 0.0, 0.0, w, h, &pal());
                let (scene_v, _) = gau_draw("powerdraw", w, h, &vals);
                assert_eq!(
                    fmt(&rust),
                    fmt(&scene_v),
                    "{} samples at {w}x{h}: the scene and the drawer must paint the same commands",
                    hist.len()
                );
            }
        }
    }

    /// The system card, one `Shell` per case and both painters.
