    #[test]
    fn ring_fit_and_ladders_follow_the_card_height() {
        // the `Half` fit: ((110 − 62) / 2).clamp(20, 34) = 24
        assert_eq!(
            RingFit::Half {
                offset: 62.0,
                min: 20.0,
                max: 34.0
            }
            .radius(110.0, scale()),
            24.0
        );
        // clamped at both ends
        assert_eq!(
            RingFit::Half {
                offset: 62.0,
                min: 20.0,
                max: 34.0
            }
            .radius(90.0, scale()),
            20.0
        );
        assert_eq!(
            RingFit::Half {
                offset: 62.0,
                min: 20.0,
                max: 34.0
            }
            .radius(200.0, scale()),
            34.0
        );
        // the ladder steps on 116 with the last step as the fallback
        let l = RingFit::Ladder(vec![(116.0, 30.0), (0.0, 22.0)]);
        assert_eq!(l.radius(140.0, scale()), 30.0);
        assert_eq!(l.radius(116.0, scale()), 30.0);
        assert_eq!(l.radius(115.0, scale()), 22.0);
        // the shared ladder helper
        let steps = [(116.0, 45.0), (0.0, 37.0)];
        assert_eq!(ladder_step(&steps, 0.0, 140.0, scale()), 45.0);
        assert_eq!(ladder_step(&steps, 0.0, 100.0, scale()), 37.0);
        assert_eq!(
            ladder_step(&[], 12.0, 100.0, scale()),
            12.0,
            "no ladder keeps the field"
        );
        assert_eq!(
            ladder_step(&[(500.0, 9.0)], 12.0, 100.0, scale()),
            12.0,
            "no match keeps the field"
        );
        // scaled cards: thresholds are base px, the box arrives scaled
        let s2 = crate::shell::GridScale(2.0);
        assert_eq!(
            l.radius(280.0, s2),
            30.0,
            "a 2x card of 140 still takes the big ring"
        );
        assert_eq!(l.radius(200.0, s2), 22.0);
    }

    #[test]
    fn when_hides_its_children_outside_the_size_window() {
        let vals = gau_vals(42, 58, 0, 8, 0.0);
        // 240x140: both the two-column and the single-column branch fit
        let (two, _) = gau_draw("gauges", 240.0, 140.0, &vals);
        assert_eq!(rects(&two).len(), 72, "two columns when w ≥ 170");
        let (one, _) = gau_draw("gauges", 169.0, 140.0, &vals);
        assert_eq!(rects(&one).len(), 36, "one column below 170");
        // the `When` bound is scaled with the card
        let s2 = crate::shell::GridScale(2.0);
        assert_eq!(s2.s(170.0), 340.0);
    }

    // ── disk / gpu / cpugpu (2026-09-27) — three `Ink` cards that became
    // fully declarative scenes, pinned against the Rust drawers they replace.

    /// Live values for the disk card: `pct` drives the warn/crit bar ink.
    fn disk_vals(parts: &[(&str, i32)]) -> SceneValues {
        let mut m = SceneValues::new();
        m.insert(
            "disk_meta",
            SceneValue::Text(if parts.is_empty() {
                String::new()
            } else {
                format!("{} mounts", parts.len())
            }),
        );
        m.insert(
            "disk_rows",
            SceneValue::Rows(
                parts
                    .iter()
                    .map(|(mount, pct)| SceneRow {
                        cols: vec![
                            mount.to_string(),
                            format!("{} GB {}%", 12 * pct, 400),
                            pct.to_string(),
                        ],
                        key: 0,
                        action: None,
                        color: None,
                        col_colors: vec![
                            Some(ColorToken::Fg2),
                            Some(ColorToken::Fg),
                            Some(if *pct >= 90 {
                                ColorToken::Danger
                            } else if *pct >= 75 {
                                ColorToken::Warn
                            } else {
                                ColorToken::Acc
                            }),
                        ],
                        surface: None,
                    })
                    .collect(),
            ),
        );
        m.insert("disk_live", SceneValue::Toggle(!parts.is_empty()));
        m.insert("disk_empty", SceneValue::Toggle(parts.is_empty()));
        m
    }

    /// Live values for the gpu card.
    fn gpu_vals(pct: i32, temp: f32, vram: Option<(u64, u64)>) -> SceneValues {
        let p = pal();
        let mut m = SceneValues::new();
        let pct = pct.max(0).clamp(0, 100);
        m.insert("gpu_pct", SceneValue::Text(format!("{pct}%")));
        m.insert("gpu_frac", SceneValue::Ring(pct as f32 / 100.0));
        m.insert(
            "gpu_temp_c",
            SceneValue::Text(format!("{temp:.0} \u{b0} C")),
        );
        m.insert("gpu_live", SceneValue::Toggle(pct > 0 || temp > 0.0));
        m.insert("gpu_empty", SceneValue::Toggle(pct == 0 && temp == 0.0));
        m.insert("gpu_vram_live", SceneValue::Toggle(vram.is_some()));
        if let Some((used, total)) = vram {
            m.insert(
                "gpu_vram_txt",
                SceneValue::Text(format!(
                    "VRAM {:.1}/{:.1} GB",
                    used as f32 / 1024.0,
                    total as f32 / 1024.0
                )),
            );
            m.insert(
                "gpu_vram_frac",
                SceneValue::Ring(used as f32 / total.max(1) as f32),
            );
        }
        let cpu_col = crate::ui::mix(p.acc, p.fg, 0.35);
        let gpu_col = crate::ui::mix(crate::ui::INFO, p.fg, 0.10);
        m.insert("cpugpu_cpu", SceneValue::Text(format!("CPU {pct}%")));
        m.insert("cpugpu_gpu", SceneValue::Text(format!("GPU {pct}%")));
        m.insert("cpugpu_gpu_live", SceneValue::Toggle(true));
        m.insert_color("cpugpu_cpu_ink", SceneColor::Raw(cpu_col));
        m.insert_color("cpugpu_gpu_ink", SceneColor::Raw(gpu_col));
        m.insert(
            "cpu_spark",
            SceneValue::Spark(vec![0.2, 0.4, 0.6, 0.5, 0.8]),
        );
        m.insert("gpu_spark", SceneValue::Spark(vec![0.1, 0.3, 0.2, 0.4]));
        m
    }

    #[test]
    fn disk_gpu_cpugpu_scenes_parse_zero_ink() {
        for id in ["disk", "gpu", "cpugpu"] {
            let Some(scene) = batt_scene(id) else { return };
            assert!(
                !scene
                    .items
                    .iter()
                    .any(|i| matches!(i, SceneItem::Ink { .. })),
                "{id} scene is fully declarative (no Ink body)"
            );
        }
        // disk: the meter rows + the centered empty caption, both gated
        let disk = batt_scene("disk").expect("scene present");
        assert!(
            disk.items
                .iter()
                .any(|i| matches!(i, SceneItem::Rows { .. })),
            "disk list is a Rows item"
        );
        let empty = disk
            .items
            .iter()
            .find_map(|i| {
                if let SceneItem::Text { text, visible, .. } = i {
                    Some((text.clone(), visible.clone()))
                } else {
                    None
                }
            })
            .expect("disk declares the empty-state caption");
        assert_eq!(empty.0, "No partitions");
        assert_eq!(
            empty.1.as_deref(),
            Some("disk_empty"),
            "empty state gated on the list"
        );
        // gpu: everything but the header lives inside the live gate
        let gpu = batt_scene("gpu").expect("scene present");
        assert!(
            gpu.items
                .iter()
                .any(|i| matches!(i, SceneItem::Stack { visible: Some(v), .. } if v == "gpu_live")),
            "the whole gpu body hides when no source exists"
        );
        // cpugpu: size-window branches only
        let cpugpu = batt_scene("cpugpu").expect("scene present");
        assert!(
            cpugpu
                .items
                .iter()
                .all(|i| matches!(i, SceneItem::When { .. })),
            "cpugpu branches on the card size window only"
        );
    }

    #[test]
    fn disk_rows_land_on_the_drawer_geometry() {
        // 300x160 card with two mounts — the drawer's own numbers
        let vals = disk_vals(&[("/", 45), ("/boot", 92)]);
        let (v, hits) = gau_draw("disk", 300.0, 160.0, &vals);
        assert!(hits.is_empty(), "a read-only list registers no regions");
        let t = texts(&v);
        let find = |needle: &str| t.iter().find(|(_, _, _, s)| s == needle).cloned();
        // mount label: fg2 9.0 at the 14 px pad, on the first row (y 32)
        let (lx, ly, lsize, _) = find("/").expect("mount label drawn");
        assert_eq!((lx, ly, lsize), (14.0, 32.0, 9.0));
        // the value cell right-anchors on the same 14 px inset
        let l2 = find("/boot").expect("second mount label");
        assert_eq!(l2.1, 56.0, "24 px row stride");
        // the meter bar: 13 px under the row top, 6 tall, r 3, full pad width
        let rs = rects(&v);
        let bar = rs
            .iter()
            .find(|r| r.1 == 45.0)
            .expect("bar 13 px under the row top");
        assert_eq!(
            (bar.0, bar.2, bar.3),
            (14.0, 272.0, 6.0),
            "bar spans the card minus both pads"
        );
        let fills: Vec<_> = rs.iter().filter(|r| r.1 == 45.0).collect();
        assert_eq!(fills.len(), 2, "track + fill");
        assert_eq!(
            fills[0].4,
            crate::ui::hover(&pal()),
            "track is the quiet hover surface"
        );
        assert_eq!(fills[1].4, pal().acc, "45% is under the warn line → accent");
        assert!(
            (fills[1].2 - 122.4).abs() < 0.5,
            "45% of the 272 px track, got {}",
            fills[1].2
        );
        // the 92% mount takes the danger ink (shared 75/90 ladder)
        let crit = rs
            .iter()
            .filter(|r| r.1 == 69.0)
            .nth(1)
            .expect("second row's fill");
        assert_eq!(crit.4, crate::ui::DANGER, "92% is past the crit line");
        assert!(
            (crit.2 - 250.24).abs() < 0.5,
            "92% of the track width, got {}",
            crit.2
        );
        // empty list → the centered caption, no rows
        let (ev, _) = gau_draw("disk", 300.0, 160.0, &disk_vals(&[]));
        let et = texts(&ev);
        assert!(
            !et.iter().any(|(_, _, _, s)| s == "/"),
            "no rows while empty"
        );
        // the empty caption still centers on the card: x is the CENTER LINE,
        // not the string's left edge, and y sits 6 px above the middle
        let (ex, ey, ecenter) = ev
            .iter()
            .find_map(|c| match c {
                Cmd::Text {
                    x, y, center, text, ..
                } if text == "No partitions" => Some((*x, *y, *center)),
                _ => None,
            })
            .expect("the centered empty caption");
        assert_eq!(
            (ex, ey),
            (150.0, 74.0),
            "the card's center line, 6 px above the middle"
        );
        assert!(ecenter, "and drawn centered about it");
    }

    #[test]
    fn gpu_body_lands_on_the_drawer_geometry() {
        // 240x140, a 45% util GPU at 60 C with 2/8 GB VRAM
        let vals = gpu_vals(45, 60.0, Some((2048, 8192)));
        let (v, _) = gau_draw("gpu", 240.0, 140.0, &vals);
        let t = texts(&v);
        let find = |needle: &str| t.iter().find(|(_, _, _, s)| s == needle).cloned();
        // hero % right-anchored on the header line, 22 px display accent
        let (_, hy, hsize, _) = find("45%").expect("util hero drawn");
        assert_eq!((hy, hsize), (24.0, 22.0));
        let (_, uy, _, _) = find("utilization").expect("caption drawn");
        assert_eq!(uy, 28.0, "4 px under the header line");
        // the util bar: 5 px tall on the 50 px line, r 2.5, pad-to-pad
        let rs = rects(&v);
        let track = rs.iter().find(|r| r.1 == 50.0).expect("util bar at y 50");
        assert_eq!(
            (track.0, track.2, track.3),
            (12.0, 216.0, 5.0),
            "bar spans the 12 px pads"
        );
        // the thermal glyph sits on the 62 px line at the pad; its mono
        // reading 14 px right, one px lower (exact Rust insets)
        let (gx, gy, gsize, _) = find("\u{f2c9}").expect("thermal glyph drawn");
        assert_eq!((gx, gy, gsize), (12.0, 62.0, 9.0), "icon font, fg2");
        let (tx, ty, tsize, _) = find("60 \u{b0} C").expect("thermal reading drawn");
        assert_eq!(
            (tx, ty, tsize),
            (26.0, 63.0, 9.5),
            "14 px right of the glyph, mono 9.5"
        );
        // the VRAM row + its 4 px bar only exist when the source reports VRAM
        assert!(find("VRAM 2.0/8.0 GB").is_some(), "vram row drawn");
        assert!(
            rs.iter().any(|r| r.1 == 89.0 && r.3 == 4.0),
            "vram bar 27 px under the temp row"
        );
        // no source at all → just the header + the empty caption
        let (nv, _) = gau_draw("gpu", 240.0, 140.0, &gpu_vals(0, 0.0, None));
        let nt = texts(&nv);
        let cap = nt
            .iter()
            .find(|(_, _, _, s)| s == "no GPU source")
            .expect("empty caption drawn");
        assert_eq!(
            cap.1, 64.0,
            "card_h / 2 − 6, like `card_empty` on a 140 px card"
        );
        assert!(
            !nt.iter().any(|(_, _, _, s)| s == "0%"),
            "no hero while empty"
        );
        assert!(
            !nt.iter().any(|(_, _, _, s)| s == "0 \u{b0} C"),
            "no temp row while empty"
        );
        assert!(rects(&nv).is_empty(), "no bars while empty");
    }

    #[test]
    fn cpugpu_legend_and_plot_follow_the_size_window() {
        // wide (≥ 170): the two legend lines in the top right + the plot from
        // y 52; narrow: no legend, plot from y 12
        let vals = gpu_vals(45, 60.0, None);
        let p = pal();
        let cpu_col = crate::ui::mix(p.acc, p.fg, 0.35);
        let (wide, _) = gau_draw("cpugpu", 200.0, 120.0, &vals);
        let t = texts(&wide);
        assert!(
            t.iter().any(|(_, _, _, s)| s == "CPU 45%"),
            "legend drawn on a wide card"
        );
        assert!(
            t.iter().any(|(_, _, _, s)| s == "GPU 45%"),
            "gpu legend drawn"
        );
        let dots: Vec<_> = rects(&wide).into_iter().filter(|r| r.2 == 8.0).collect();
        assert_eq!(dots.len(), 2, "two 8 px legend dots");
        assert_eq!(dots[0].1, 18.0, "cpu dot on the 18 px line");
        assert_eq!(dots[1].1, 39.0, "gpu dot 21 px lower");
        assert_eq!(
            dots[0].4, cpu_col,
            "cpu dot follows the mode-adjusted accent"
        );
        // the plot: 4 gpu + 5 cpu samples → 3 + 4 line segments, GPU under CPU
        let lines: Vec<(f32, f32, f32, f32)> = wide
            .iter()
            .filter_map(|c| match c {
                Cmd::Line { x0, y0, x1, y1, .. } => Some((*x0, *y0, *x1, *y1)),
                _ => None,
            })
            .collect();
        assert_eq!(lines.len(), 7, "one segment per gap: 3 gpu + 4 cpu");
        assert_eq!(
            lines[0].0, 14.0,
            "the gpu series draws first, from the plot's left edge"
        );
        // x 14, w -14, y 52, h -14 → box x 14..186, y 52..106 on a 200x120 card
        assert!(
            lines
                .iter()
                .all(|l| l.1 >= 52.0 && l.1 <= 106.0 && l.3 >= 52.0 && l.3 <= 106.0),
            "every sample stays inside the plot box, got {lines:?}"
        );
        assert_eq!(
            lines.last().unwrap().2,
            186.0,
            "the cpu series ends 14 px short of the card edge"
        );
        // narrow: no legend, the plot box moves up to the 12 px line
        let (narrow, _) = gau_draw("cpugpu", 160.0, 120.0, &vals);
        let nt = texts(&narrow);
        assert!(
            !nt.iter().any(|(_, _, _, s)| s == "CPU 45%"),
            "no legend below 170 px"
        );
        let nlines: Vec<(f32, f32, f32, f32)> = narrow
            .iter()
            .filter_map(|c| match c {
                Cmd::Line { x0, y0, x1, y1, .. } => Some((*x0, *y0, *x1, *y1)),
                _ => None,
            })
            .collect();
        assert_eq!(nlines.len(), 7, "same two series");
        assert_eq!(nlines[0].0, 14.0);
        assert!(
            nlines
                .iter()
                .all(|l| l.1 >= 12.0 && l.1 <= 106.0 && l.3 >= 12.0 && l.3 <= 106.0),
            "narrow box is y 12 .. 106, got {nlines:?}"
        );
        assert_eq!(nlines.last().unwrap().2, 146.0, "inset 14 on a 160 px card");
    }

    /// Dual-series graph values: two normalized 0..1 series per card.
    fn spark_vals(a: &str, b: &str) -> SceneValues {
        let mut m = SceneValues::new();
        m.insert(a, SceneValue::Spark(vec![0.1, 0.4, 0.25, 0.8]));
        m.insert(b, SceneValue::Spark(vec![0.6, 0.2, 0.5, 0.3]));
        m
    }

    fn line_bounds(v: &[Cmd]) -> Vec<(f32, f32, f32, f32)> {
        v.iter()
            .filter_map(|c| match c {
                Cmd::Line { x0, y0, x1, y1, .. } => Some((*x0, *y0, *x1, *y1)),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn graph_cards_inset_their_plot_box_on_both_sides() {
        // A negative `w`/`h` on a Spark measures against the span LEFT from
        // its own x/y, so a plot can declare symmetric insets. Three cards
        // rely on it — network, diskio, cpugpu — and all three used to draw
        // their graphs flush to the card's right/bottom edge.
        let (nv, _) = gau_draw(
            "network",
            240.0,
            140.0,
            &spark_vals("net_down_spark", "net_up_spark"),
        );
        let nl = line_bounds(&nv);
        assert_eq!(nl.len(), 6, "two series x three segments");
        // network: x 12, w -12, y 28, h -21 -> x 12..228, y 28..119
        assert!(
            nl.iter().all(|l| l.0 >= 12.0 && l.0 <= 228.0),
            "plot stays in the 12 px pads: {nl:?}"
        );
        assert!(
            nl.iter().all(|l| l.1 >= 28.0 && l.1 <= 119.0),
            "plot stops 21 px short of the bottom: {nl:?}"
        );
        assert_eq!(
            nl.iter().map(|l| l.0).fold(f32::MAX, f32::min),
            12.0,
            "left edge on the pad"
        );
        assert_eq!(
            nl.iter().map(|l| l.2).fold(0.0, f32::max),
            228.0,
            "right edge 12 px in"
        );

        let (dv, _) = gau_draw(
            "diskio",
            240.0,
            140.0,
            &spark_vals("disk_r_spark", "disk_w_spark"),
        );
        let dl = line_bounds(&dv);
        assert_eq!(dl.len(), 6, "two series x three segments");
        // diskio: x 14, w -14, y 46, h -12 -> x 14..226, y 46..128
        assert!(
            dl.iter().all(|l| l.0 >= 14.0 && l.0 <= 226.0),
            "plot stays in the 14 px pads: {dl:?}"
        );
        assert!(
            dl.iter().all(|l| l.1 >= 46.0 && l.1 <= 128.0),
            "plot stops 12 px short of the bottom: {dl:?}"
        );

        // and the room checks the Rust drawers applied, expressed as `When`
        let tall = spark_vals("net_down_spark", "net_up_spark");
        let (short, _) = gau_draw("network", 240.0, 58.0, &tall);
        assert!(
            line_bounds(&short).is_empty(),
            "a 58 px network card has no graph (drawer: gh < 10)"
        );
        let (ok58, _) = gau_draw("network", 240.0, 59.0, &tall);
        assert_eq!(
            line_bounds(&ok58).len(),
            6,
            "one px taller and the graph returns"
        );
        let dvals = spark_vals("disk_r_spark", "disk_w_spark");
        let (dshort, _) = gau_draw("diskio", 240.0, 77.0, &dvals);
        assert!(
            line_bounds(&dshort).is_empty(),
            "a 77 px diskio card has no graph (drawer: plot_h < 20)"
        );
        let (dok, _) = gau_draw("diskio", 240.0, 78.0, &dvals);
        assert_eq!(
            line_bounds(&dok).len(),
            6,
            "one px taller and the graph returns"
        );
    }

    /// Speed-test values for one of the three probe states.
    fn speed_vals(state: i32) -> SceneValues {
        let p = &pal();
        let mut m = SceneValues::new();
        let testing = state == 1;
        let done = state == 2;
        m.insert("st_idle", SceneValue::Toggle(state == 0));
        m.insert("st_testing", SceneValue::Toggle(testing));
        m.insert("st_done", SceneValue::Toggle(done));
        m.insert("st_clickable", SceneValue::Toggle(!testing));
        m.insert("st_down", SceneValue::Text("down 942 Mbps".into()));
        m.insert("st_up", SceneValue::Text("up 87 Mbps".into()));
        m.insert("st_ping", SceneValue::Text("ping 11 ms".into()));
        m.insert_color(
            "st_state_ink",
            if done {
                SceneColor::Raw(crate::ui::OK)
            } else {
                SceneColor::Raw(crate::ui::fg3(p))
            },
        );
        let (fill, ink) = if testing {
            (
                crate::ui::mix(crate::ui::hover(p), p.fg, 0.10),
                crate::ui::fg3(p),
            )
        } else {
            (p.acc, 0xff14_14_14)
        };
        m.insert_color("st_btn_fill", SceneColor::Raw(fill));
        m.insert_color("st_btn_ink", SceneColor::Raw(ink));
        m.insert(
            "st_btn_label",
            SceneValue::Text(if testing {
                "testing\u{2026}".to_string()
            } else if done {
                format!("{}  run again", crate::icons::ICON_REFRESH)
            } else {
                format!("{}  run test", crate::icons::ICON_PLAY)
            }),
        );
        m.insert(
            "speed_meta",
            SceneValue::Text(match state {
                1 => "testing\u{2026}".into(),
                2 => "done".into(),
                _ => "idle".into(),
            }),
        );
        m
    }

    #[test]
    fn speedtest_scene_is_zero_ink() {
        let scene = batt_scene("speedtest").expect("scene present");
        assert!(
            !scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Ink { .. })),
            "the run button + state captions live in the scene, not the Rust body"
        );
        // three state captions, one per state — each behind its own Toggle
        let gated: Vec<&str> = scene
            .items
            .iter()
            .filter_map(|i| match i {
                SceneItem::Text {
                    text,
                    visible: Some(v),
                    ..
                } if text.starts_with("probing") || text == "click to measure" => {
                    Some(Box::leak(v.clone().into_boxed_str()) as &str)
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            gated,
            ["st_testing", "st_idle"],
            "idle + probing captions only"
        );
    }

    #[test]
    fn speedtest_lands_on_the_drawer_geometry() {
        // 200x140 card — the drawer's own numbers
        let (v, hits) = gau_draw("speedtest", 200.0, 140.0, &speed_vals(0));
        let t = texts(&v);
        // run pill: 12 px insets, 30 tall, bottom edge 8 px up, fully rounded
        let rs = rects(&v);
        let pill = rs
            .iter()
            .find(|r| r.3 == 30.0)
            .unwrap_or_else(|| panic!("run pill drawn, got {rs:?}"));
        assert_eq!(
            (pill.0, pill.1, pill.2),
            (12.0, 102.0, 176.0),
            "h - 38 .. h - 8, 12 px pads"
        );
        assert_eq!(pill.4, pal().acc, "idle pill is the flat accent");
        // the label rides the pill's own center, 6 px up like `text_c`
        let lbl = t
            .iter()
            .find(|(_, _, _, s)| s.contains("run test"))
            .expect("button label");
        assert_eq!(
            (lbl.0, lbl.1),
            (100.0, 111.0),
            "pill center 117 − 6, centered on the card"
        );
        // the idle caption sits at card_h / 2 − 15 (body_h / 2 − 6 under the header)
        let cap = t
            .iter()
            .find(|(_, _, _, s)| s == "click to measure")
            .expect("idle caption");
        assert_eq!(
            (cap.0, cap.1),
            (100.0, 55.0),
            "centered on a 200 px card, 15 above middle"
        );
        // exactly one hit region — the run button
        assert_eq!(hits.len(), 1, "button-only card");
        assert_eq!(
            hits[0].key,
            crate::shell::SPEED_KEY_BASE,
            "wires the Rust click path"
        );
        assert_eq!(
            (hits[0].x, hits[0].y, hits[0].w, hits[0].h),
            (12.0, 102.0, 176.0, 30.0)
        );
    }

    #[test]
    fn speedtest_states_swap_body_button_and_hit() {
        // done: three mono figures in equal thirds, OK-green meta, refresh label
        let (v, hits) = gau_draw("speedtest", 240.0, 140.0, &speed_vals(2));
        let t = texts(&v);
        let find = |needle: &str| t.iter().find(|(_, _, _, s)| s == needle).cloned();
        // `text_cw` emits the string's CENTER x, so the three figures anchor
        // on the thirds' centers: 240/6, 240/2, 240·5/6
        let (dx, dy, dsize, _) = find("down 942 Mbps").expect("down figure");
        assert!((dx - 40.0).abs() < 0.01, "first third, got {dx}");
        assert_eq!(dsize, 10.0);
        let (ux, uy, _, _) = find("up 87 Mbps").expect("up figure");
        assert!((ux - 120.0).abs() < 0.01, "middle third, got {ux}");
        assert_eq!(uy, dy, "same line");
        let (px, py, _, _) = find("ping 11 ms").expect("ping figure");
        assert!((px - 200.0).abs() < 0.01, "last third, got {px}");
        assert_eq!(py, dy, "same line");
        let meta = find("done").expect("header meta");
        assert_eq!(meta.3, "done");
        let lbl = t
            .iter()
            .find(|(_, _, _, s)| s.contains("run again"))
            .expect("refresh label");
        assert!(
            lbl.3.contains(crate::icons::ICON_REFRESH),
            "done re-runs with the refresh glyph"
        );
        // the pill keeps the accent fill and the region
        let pill = rects(&v)
            .into_iter()
            .find(|r| r.3 == 30.0)
            .expect("run pill");
        assert_eq!(pill.4, pal().acc);
        assert_eq!(hits.len(), 1, "still clickable after a run");

        // testing: the probing caption, the dimmed pill, NO hit region
        let (v, hits) = gau_draw("speedtest", 240.0, 140.0, &speed_vals(1));
        let t = texts(&v);
        assert!(
            t.iter()
                .any(|(_, _, _, s)| s == "probing Cloudflare edge\u{2026}"),
            "probing caption"
        );
        assert!(
            !t.iter().any(|(_, _, _, s)| s == "down 942 Mbps"),
            "no figures while probing"
        );
        let pill = rects(&v)
            .into_iter()
            .find(|r| r.3 == 30.0)
            .expect("run pill");
        assert_eq!(
            pill.4,
            crate::ui::mix(crate::ui::hover(&pal()), pal().fg, 0.10),
            "quiet pill while running"
        );
        assert!(
            hits.is_empty(),
            "the drawer registers no region while a probe is in flight"
        );
        // two "testing…" strings on this card: the header meta (right-anchored
        // at 240 − 12) and the pill label (card center, 240 − 29)
        let runs: Vec<&(f32, f32, f32, String)> = t
            .iter()
            .filter(|(_, _, _, s)| s == "testing\u{2026}")
            .collect();
        assert_eq!(runs.len(), 2, "meta + pill label");
        assert_eq!(
            (runs[0].0, runs[0].1),
            (228.0, 11.0),
            "header meta, right-anchored on the 8.5 meta line"
        );
        assert_eq!(
            (runs[1].0, runs[1].1),
            (120.0, 111.0),
            "pill label centered on the pill"
        );
    }

    /// micmeter card (2026-09-27): the level bar + caption + mute button moved
    /// into the scene; the Rust drawer stays the geometry of record.
    fn mic_vals(level: f32, muted: bool, hov: bool) -> SceneValues {
        let p = &pal();
        let mut m = SceneValues::new();
        m.insert(
            "mic_meta",
            SceneValue::Text(format!("{:>3}%", (level * 100.0).round() as i32)),
        );
        m.insert("mic_icon", SceneValue::Text(crate::icons::ICON_MIC.into()));
        let lvl = if muted { 0.0 } else { level.clamp(0.0, 1.0) };
        m.insert("mic_lvl", SceneValue::Text(format!("{lvl:.4}")));
        m.insert_color(
            "mic_bar_ink",
            if muted {
                SceneColor::Raw(crate::ui::fg3(p))
            } else if lvl > 0.9 {
                SceneColor::Raw(crate::ui::DANGER)
            } else {
                SceneColor::Raw(p.acc)
            },
        );
        m.insert(
            "mic_status",
            SceneValue::Text(if muted {
                "muted".into()
            } else if lvl > 0.05 {
                "live".into()
            } else {
                "quiet".into()
            }),
        );
        m.insert_color(
            "mic_status_ink",
            if muted {
                SceneColor::Raw(crate::ui::fg3(p))
            } else if lvl > 0.9 {
                SceneColor::Raw(crate::ui::DANGER)
            } else {
                SceneColor::Raw(crate::ui::fg2(p))
            },
        );
        m.insert_color(
            "mic_btn_fill",
            SceneColor::Raw(if hov {
                crate::ui::raised_hl(p)
            } else {
                crate::ui::raised(p)
            }),
        );
        m.insert_color(
            "mic_btn_ink",
            SceneColor::Raw(if muted { p.acc } else { crate::ui::fg2(p) }),
        );
        m.insert(
            "mic_btn_label",
            SceneValue::Text(format!(
                "{} {}",
                if muted {
                    crate::icons::ICON_MIC_OFF
                } else {
                    crate::icons::ICON_MIC
                },
                if muted { "Unmute mic" } else { "Mute mic" }
            )),
        );
        m
    }

    /// docker card (2026-09-27): the container list went declarative; the Rust
    /// drawer stays the geometry of record.
    fn docker_vals(containers: &[(&str, &str, &str)]) -> SceneValues {
        let mut m = SceneValues::new();
        let rows: Vec<SceneRow> = containers
            .iter()
            .map(|(name, status, image)| SceneRow {
                cols: vec![String::new(), (*name).to_string(), (*image).to_string()],
                key: 0,
                action: None,
                color: None,
                surface: None,
                col_colors: vec![Some(if status.contains("Up") {
                    ColorToken::Ok
                } else {
                    ColorToken::Danger
                })],
            })
            .collect();
        m.insert("docker_empty", SceneValue::Toggle(rows.is_empty()));
        m.insert("docker_rows", SceneValue::Rows(rows));
        m
    }

    #[test]
    fn docker_scene_is_zero_ink() {
        let scene = batt_scene("docker").expect("scene present");
        assert!(
            !scene
                .items
                .iter()
                .any(|i| matches!(i, SceneItem::Ink { .. })),
            "the list is Rows, not Rust"
        );
        let rows = scene
            .items
            .iter()
            .find_map(|i| match i {
                SceneItem::Rows { name, cols, .. } => Some((name.as_str(), cols.len())),
                _ => None,
            })
            .expect("a Rows list");
        assert_eq!(rows, ("docker_rows", 3), "dot + name + image columns");
    }

    #[test]
    fn docker_rows_land_on_the_drawer_geometry() {
        // 200x140 card: 14 px pad, rows from 32 on a 26 px pitch, the 6 px dot
        // at the row's left edge + 3, the name 10 px in at 9 px, and the image
        // right-anchored at the 14 px inset.
        let vals = docker_vals(&[
            ("web", "Up 3 hours", "nginx:latest"),
            ("db", "Exited (0) 2 days ago", "postgres:16-alpine"),
        ]);
        let (v, _) = gau_draw("docker", 200.0, 140.0, &vals);
        let rs = rects(&v);
        // two 6x6 dots, 3 px below each row's top
        let dots: Vec<&(f32, f32, f32, f32, u32)> =
            rs.iter().filter(|r| r.2 == 6.0 && r.3 == 6.0).collect();
        assert_eq!(dots.len(), 2, "one status dot per container");
        assert_eq!(
            (dots[0].0, dots[0].1),
            (14.0, 35.0),
            "14 px pad, +3 into the row"
        );
        assert_eq!((dots[1].0, dots[1].1), (14.0, 61.0), "26 px row pitch");
        assert_eq!(dots[0].4, crate::ui::OK, "Up = the muted OK green");
        assert_eq!(
            dots[1].4,
            crate::ui::DANGER,
            "anything else = the danger red"
        );
        // the names
        let t = texts(&v);
        let name = t
            .iter()
            .find(|(_, _, _, s)| s == "web")
            .expect("the first name");
        assert_eq!(
            (name.0, name.1),
            (24.0, 32.0),
            "10 px past the dot, on the row's top"
        );
        assert_eq!(name.2, 9.0, "9 px");
        // the image label, right-anchored at the 14 px inset at 7.5 px
        let img = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text {
                    x,
                    y,
                    right,
                    size,
                    text,
                    ..
                } if text == "nginx:latest" => Some((*x, *y, *right, *size)),
                _ => None,
            })
            .expect("the image label");
        assert_eq!(
            (img.0, img.1),
            (186.0, 32.0),
            "right edge at card_w - 14, on the row's top"
        );
        assert!(img.2, "right-anchored, so the label grows leftward");
        assert_eq!(img.3, 7.5, "7.5 px");
    }

    #[test]
    fn docker_caps_its_rows_and_shows_one_caption_when_empty() {
        // the drawer's `floor((h - 36) / 26)` cap: at 140 tall that is 4 rows
        let many: Vec<(String, String, String)> = (0..8)
            .map(|i| (format!("c{i}"), "Up".to_string(), format!("img{i}:latest")))
            .collect();
        let vals = docker_vals(
            &many
                .iter()
                .map(|(a, b, c)| (a.as_str(), b.as_str(), c.as_str()))
                .collect::<Vec<_>>(),
        );
        let (v, _) = gau_draw("docker", 200.0, 140.0, &vals);
        let t = texts(&v);
        let names: Vec<&String> = t
            .iter()
            .filter(|(_, _, _, s)| s.starts_with("img"))
            .map(|(_, _, _, s)| s)
            .collect();
        assert_eq!(names.len(), 4, "four rows fit above card_h - 4");
        assert_eq!(
            *names.last().unwrap(),
            "img3:latest",
            "the fifth would cross the bottom cap"
        );
        // the empty state: one centered caption, no rows
        let vals = docker_vals(&[]);
        let (v, _) = gau_draw("docker", 200.0, 140.0, &vals);
        assert!(rects(&v).is_empty(), "no rows, no dots");
        let cap = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text {
                    x, y, text, center, ..
                } if text == "No containers" => Some((*x, *y, *center)),
                _ => None,
            })
            .expect("the empty caption");
        assert_eq!((cap.0, cap.1), (100.0, 70.0), "centered on the card");
        assert!(cap.2, "and centered, not left-anchored");
    }

    #[test]
    fn a_dot_cell_paints_its_own_ink_and_a_char_cap_truncates() {
        // the two new cell kinds in isolation: a text-less dot (inked by
        // `col_colors`) and the 20-character image cap
        let scene: CardScene = parse_scene_ron(
            r#"(items: [ Rows(
                    name: "r", y: 0.0, row_h: 20.0, w: 0.0, pad: 10.0, row_dy: 0.0,
                    cols: [
                        SceneCol(x: 0.0, dot: Some(DotSpec(size: 6.0, top: 2.0))),
                        SceneCol(x: 10.0, size: 9.0, max_chars: Some(5)),
                    ],
                ) ])"#,
        )
        .unwrap();
        let mut m = SceneValues::new();
        m.insert(
            "r",
            SceneValue::Rows(vec![SceneRow {
                cols: vec![String::new(), "abcdefghij".into()],
                key: 0,
                action: None,
                color: None,
                surface: None,
                col_colors: vec![Some(ColorToken::Warn)],
            }]),
        );
        let mut v: Vec<Cmd> = Vec::new();
        scene.draw(
            &mut v,
            0.0,
            0.0,
            200.0,
            60.0,
            scale(),
            &pal(),
            &m,
            0,
            true,
            true,
        );
        let dot = rects(&v)
            .into_iter()
            .find(|r| r.2 == 6.0 && r.3 == 6.0)
            .expect("the dot");
        assert_eq!(
            (dot.0, dot.1),
            (10.0, 2.0),
            "at the cell's x, `top` into the row"
        );
        assert_eq!(dot.4, crate::ui::WARN, "inked by col_colors");
        assert!(
            texts(&v).iter().any(|(_, _, _, s)| s == "abcde"),
            "the cell is capped at 5 chars"
        );
        assert!(
            !texts(&v).iter().any(|(_, _, _, s)| s.len() > 5),
            "nothing longer survives"
        );
    }

    /// alarms card (2026-09-27): the whole card went declarative.
    fn alarm_vals(list: &[(&str, &str)], input: Option<&str>) -> SceneValues {
        let mut m = SceneValues::new();
        let composing = input.is_some();
        let buf = input.unwrap_or("");
        m.insert(
            "alarm_meta",
            SceneValue::Text(if list.is_empty() {
                String::new()
            } else {
                format!("{} set", list.len())
            }),
        );
        m.insert_color(
            "alarm_fill",
            SceneColor::Token(if composing {
                ColorToken::HoverHl
            } else {
                ColorToken::Hover
            }),
        );
        m.insert_color(
            "alarm_ink",
            SceneColor::Token(if buf.is_empty() {
                ColorToken::Fg3
            } else {
                ColorToken::Fg
            }),
        );
        m.insert(
            "alarm_input",
            SceneValue::Text(if buf.is_empty() {
                "add alarm — 07:30 stand up".to_string()
            } else {
                buf.to_string()
            }),
        );
        m.insert(
            "alarm_rows",
            SceneValue::Rows(
                list.iter()
                    .map(|(t, l)| SceneRow {
                        cols: vec![(*t).to_string(), (*l).to_string()],
                        key: 0,
                        action: None,
                        color: None,
                        surface: None,
                        col_colors: vec![],
                    })
                    .collect(),
            ),
        );
        m
    }

