    #[test]
    fn alarm_composer_and_rows_land_on_the_drawer_geometry() {
        // 300x160 card, two alarms — the drawer's own numbers
        let vals = alarm_vals(&[("06:15", "gym"), ("07:30", "stand up")], None);
        let (v, hits) = gau_draw("alarms", 300.0, 160.0, &vals);
        // the composer well: 12 px pad, 22 tall at y 26, radius 6, `hover`
        let rs = rects(&v);
        let well = rs.iter().find(|r| r.3 == 22.0).expect("the composer well");
        assert_eq!(
            (well.0, well.1, well.2),
            (12.0, 26.0, 276.0),
            "12 px pad both sides"
        );
        assert_eq!(
            well.4,
            crate::ui::hover(&pal()),
            "idle composer is the quiet well"
        );
        // its label: 8 px in, 5 px down, 8.5
        let t = texts(&v);
        let lbl = t
            .iter()
            .find(|(_, _, _, s)| s.starts_with("add alarm"))
            .expect("the placeholder");
        assert_eq!((lbl.0, lbl.1, lbl.2), (20.0, 31.0, 8.5));
        let meta = t
            .iter()
            .find(|(_, _, _, s)| s == "2 set")
            .expect("the count");
        assert_eq!(
            meta.0, 288.0,
            "right-anchored at the 12 px pad (the drawer's `x + w - pad`)"
        );
        // rows from y 50 on the 24 px pitch: mono accent time, then the label
        let tm = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text {
                    x,
                    y,
                    size,
                    text,
                    f,
                    ..
                } if text == "06:15" => Some((*x, *y, *size, *f)),
                _ => None,
            })
            .expect("the first alarm time");
        assert_eq!(tm.0, 12.0, "at the 12 px pad");
        assert_eq!(tm.1, 53.0, "3 px into the row");
        assert_eq!(tm.2, 10.0, "10.0");
        assert!(
            matches!(tm.3, crate::text::Ff::Mono),
            "mono, the drawer's `ui::text_mono`"
        );
        let name = t
            .iter()
            .find(|(_, _, _, s)| s == "stand up")
            .expect("the second alarm label");
        assert_eq!(
            (name.0, name.1, name.2),
            (62.0, 77.0, 9.5),
            "50 px in, on the second row"
        );
        // only the composer's region registers — the list itself is inert
        let keys: Vec<u32> = hits.iter().map(|r| r.key).collect();
        assert_eq!(
            keys,
            vec![31_600],
            "the composer takes the click; rows have no key"
        );
    }

    #[test]
    fn the_alarm_x_reveals_on_hover_and_its_key_turns_it_red() {
        let scene = batt_scene("alarms").expect("scene present");
        let vals = alarm_vals(&[("07:30", "stand up")], None);
        // row hovered: the ✕ appears 26 px from the card's right edge, 4 px
        // into the row, at 9.0 — painted fg until the pointer is on it
        let draw = |hover: u32| {
            let mut v: Vec<Cmd> = Vec::new();
            let (hits, _) = scene.draw(
                &mut v,
                0.0,
                0.0,
                300.0,
                160.0,
                scale(),
                &pal(),
                &vals,
                hover,
                true,
                true,
            );
            (v, hits)
        };
        let x = |v: &[Cmd]| {
            v.iter().find_map(|c| match c {
                Cmd::Text {
                    x, y, size, text, ..
                } if text == crate::icons::ICON_CLOSE => Some((*x, *y, *size)),
                _ => None,
            })
        };
        let (idle, _) = draw(0);
        assert!(x(&idle).is_none(), "no ✕ until the row is hovered");
        let (xv, hits) = draw(31_610);
        assert_eq!(
            x(&xv),
            Some((300.0 - 26.0, 54.0, 9.0)),
            "at the pad + 14, 4 px into the row"
        );
        let del = hits
            .iter()
            .find(|r| r.key == 31_610)
            .expect("the delete region");
        assert_eq!(
            (del.y, del.h),
            (46.0, 22.0),
            "a 22 px target around the glyph"
        );
        let fg = xv
            .iter()
            .find_map(|c| match c {
                Cmd::Text { text, color, .. } if text == crate::icons::ICON_CLOSE => Some(*color),
                _ => None,
            })
            .unwrap();
        assert_eq!(
            fg,
            crate::ui::DANGER,
            "red the moment the pointer is on the ✕ itself"
        );
    }

