    #[test]
    fn the_latency_plot_lands_on_the_drawer_geometry() {
        // 300x160 card: plot 12,32 → 218x116. The series [24, 240, 120]
        // normalizes against a 240 ms peak → [0.1, 1.0, 0.5]; the Line
        // spark's 2 px weight insets its ends by pad = 2, so a point sits at
        // 32 + 116 − 2 − d·112 and the step is 218/2 = 109
        let (v, hits) = gau_draw("latency", 300.0, 160.0, &lat_vals(2, 240, &[24, 240, 120]));
        let ls = lines(&v);
        assert_eq!(ls.len(), 2, "two spark segments, got {ls:?}");
        assert_eq!(ls[0], (12.0, 134.8, 121.0, 34.0, 2.0), "0.1 → 146 − 11.2");
        assert_eq!(
            ls[1],
            (121.0, 34.0, 230.0, 90.0, 2.0),
            "peak tops out, then the 0.5 tail"
        );
        // the hero readout rides h/2 + 17, right-anchored 12 px in
        let t = texts(&v);
        let hero = t
            .iter()
            .find(|(_, _, _, s)| s == "240")
            .expect("hero drawn");
        assert_eq!(
            (hero.0, hero.1, hero.2),
            (288.0, 97.0, 20.0),
            "h/2 + 17 at the right margin"
        );
        let unit = t.iter().find(|(_, _, _, s)| s == "ms").expect("unit drawn");
        assert_eq!((unit.0, unit.1, unit.2), (288.0, 83.0, 7.5), "h/2 + 3");
        let status = t
            .iter()
            .find(|(_, _, _, s)| s == "bad")
            .expect("status drawn");
        assert_eq!((status.0, status.1), (12.0, 137.0), "x 12, top h − 23");
        // the re-probe pill: 30x20 r6, 12 px off the right edge, bottom 8 —
        // plus its 3 px halo, both on LATENCY_RUN_KEY
        let pill = rects(&v)
            .into_iter()
            .find(|r| r.2 == 30.0)
            .unwrap_or_else(|| panic!("pill drawn, got {:?}", rects(&v)));
        assert_eq!(
            (pill.0, pill.1, pill.2, pill.3),
            (258.0, 132.0, 30.0, 20.0),
            "30x20 pill, r 6"
        );
        let run_hits: Vec<_> = hits.iter().filter(|h| h.key == 31_970).collect();
        assert_eq!(
            run_hits.len(),
            2,
            "the pill + its halo both hit LATENCY_RUN_KEY"
        );
        let halo = run_hits.iter().find(|h| h.w == 36.0).expect("halo region");
        assert_eq!(
            (halo.x, halo.y, halo.h),
            (255.0, 129.0, 26.0),
            "3 px out on every side"
        );
    }

