    #[test]
    fn micmeter_lands_on_the_drawer_geometry() {
        // 200x140 card — the drawer's own numbers: 12 px pad, 22 px header,
        // the bar at 34 (22 + 12) 8 tall, the caption 16 below it, the button
        // 22 tall with its bottom 12 px up, and the click halo 3 px out.
        let (v, hits) = gau_draw("micmeter", 200.0, 140.0, &mic_vals(0.65, false, false));
        // the bar's track: 12 px insets, y 34, 8 tall, fully rounded
        let rs = rects(&v);
        let track = rs
            .iter()
            .find(|r| r.3 == 8.0)
            .unwrap_or_else(|| panic!("the level track, got {rs:?}"));
        assert_eq!(
            (track.0, track.1, track.2),
            (12.0, 34.0, 176.0),
            "12 px insets, y 34"
        );
        assert_eq!(
            track.4,
            crate::ui::hover(&pal()),
            "the track is the hover token"
        );
        let fill = rs
            .iter()
            .find(|r| r.3 == 8.0 && r.2 < 176.0)
            .unwrap_or_else(|| panic!("the level fill, got {rs:?}"));
        assert!(
            (fill.2 - 176.0 * 0.65).abs() < 0.6,
            "the fill is 65% of the track: {}",
            fill.2
        );
        assert_eq!(
            fill.4,
            pal().acc,
            "the fill is the accent below the clip threshold"
        );
        // the status caption
        let st = texts(&v)
            .into_iter()
            .find(|(_, _, _, t)| t == "live")
            .expect("the live caption");
        assert_eq!(
            (st.0, st.1),
            (12.0, 50.0),
            "caption at the bar's left, 16 px below it"
        );
        // the mute button
        let btn = rs
            .iter()
            .find(|r| r.3 == 22.0)
            .unwrap_or_else(|| panic!("the mute button, got {rs:?}"));
        assert_eq!(
            (btn.0, btn.1, btn.2),
            (12.0, 106.0, 176.0),
            "12 px insets, bottom 12 px up"
        );
        assert_eq!(
            btn.4,
            crate::ui::raised(&pal()),
            "the resting fill is `raised`"
        );
        // its label, centered on the card, 6 px below the button's top
        let lbl = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text {
                    x, y, text, color, ..
                } if text.contains("Mute mic") => Some((*x, *y, *color)),
                _ => None,
            })
            .expect("the mute label");
        assert!(
            (lbl.0 - 100.0).abs() < 0.01 && (lbl.1 - 112.0).abs() < 0.01,
            "label center + lift: {:?}",
            (lbl.0, lbl.1)
        );
        assert_eq!(lbl.2, crate::ui::fg2(&pal()), "the label is fg2 while live");
        // the halo region
        assert_eq!(hits.len(), 1, "one clickable region");
        assert_eq!(
            (hits[0].x, hits[0].y, hits[0].w, hits[0].h),
            (9.0, 103.0, 182.0, 28.0),
            "3 px halo on every side"
        );
    }

    #[test]
    fn micmeter_mutes_collapse_the_bar_and_hover_lifts_the_button() {
        // muted: the level collapses to 0 (no fill at all), the bar + caption
        // go dim, and the label swaps to the accented "Unmute mic"
        let (v, hits) = gau_draw("micmeter", 200.0, 140.0, &mic_vals(0.65, true, true));
        let rs = rects(&v);
        assert!(
            !rs.iter().any(|r| r.3 == 8.0 && r.2 < 176.0),
            "a muted mic paints no fill"
        );
        // the drawer still paints the hover track at rest — a muted mic is a
        // flat track, which is why its dim ink rides the caption
        assert_eq!(
            rs.iter().find(|r| r.3 == 8.0).unwrap().4,
            crate::ui::hover(&pal()),
            "the track is the hover token"
        );
        let cap = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text {
                    x, y, text, color, ..
                } if text == "muted" => Some((*x, *y, *color)),
                _ => None,
            })
            .expect("the caption reads muted");
        assert_eq!(
            (cap.0, cap.1),
            (12.0, 50.0),
            "same spot as the live caption"
        );
        assert_eq!(cap.2, crate::ui::fg3(&pal()), "and goes dim");
        let lbl = v
            .iter()
            .find_map(|c| match c {
                Cmd::Text { text, color, .. } if text.contains("Unmute mic") => Some(*color),
                _ => None,
            })
            .expect("swap");
        assert_eq!(lbl, pal().acc, "the muted affordance is the accent");
        assert_eq!(
            rs.iter().find(|r| r.3 == 22.0).unwrap().4,
            crate::ui::raised_hl(&pal()),
            "the hovered button lifts"
        );
        assert_eq!(
            hits[0].key,
            crate::shell::MIC_MUTE_KEY,
            "the same key while muted"
        );
    }

    // ── implicit sizing (the bar's `auto` clusters) ──
    #[test]
    fn auto_text_measures_itself_and_drives_the_row_layout() {
        // a `Row` of auto strings packs to their content and hands each one a
        // box exactly its measured width — the engine's house estimator
        let scene: CardScene = parse_scene_ron(
            r#"( items: [
                Row(x: 0.0, y: 0.0, w: 0.0, h: 0.0, auto: true, spacing: 6.0, items: [
                    Text(x: 0.0, y: 0.0, text: "ab", font_size: 10.0, auto: true),
                    Text(x: 0.0, y: 0.0, text: "{b}", font_size: 10.0, auto: true),
                ]),
            ] )"#,
        )
        .expect("auto scene parses");
        let mut vals = SceneValues::new();
        vals.insert("b", SceneValue::Text("cde".into()));
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            400.0,
            40.0,
            scale(),
            &pal(),
            &vals,
            0,
            false,
            false,
        );
        assert!(hits.is_empty(), "text-only");
        let xs: Vec<f32> = v
            .iter()
            .filter_map(|c| match c {
                Cmd::Text { x, .. } => Some(*x),
                _ => None,
            })
            .collect();
        assert_eq!(xs.len(), 2, "both strings draw");
        // 2 chars · 0.62 · 10 = 12.4, then the declared 6 px gap
        assert!(
            (xs[1] - xs[0] - (12.4 + 6.0)).abs() < 0.01,
            "second string rides the measured width + gap, got {}",
            xs[1] - xs[0]
        );
    }

    #[test]
    fn auto_stack_snugs_a_full_width_hit_around_a_label() {
        // a `Stack { auto: true }` is as wide as its widest child, so a
        // `w: 0` hit region becomes a chip-sized click target (the bar's
        // clock / date / battery chips) instead of a card-wide one
        let scene: CardScene = parse_scene_ron(
            r#"( items: [
                Row(x: 10.0, y: 0.0, w: -20.0, h: 30.0, auto: true, spacing: 4.0, items: [
                    Stack(auto: true, items: [
                        Hit(x: -2.0, y: 4.0, w: 0.0, h: 22.0, r: 0.0, key: 70),
                        Text(x: 0.0, y: 6.0, text: "abcd", font_size: 14.0, auto: true),
                    ]),
                ]),
            ] )"#,
        )
        .expect("auto stack parses");
        let mut v: Vec<Cmd> = Vec::new();
        let (hits, _) = scene.draw(
            &mut v,
            0.0,
            0.0,
            400.0,
            40.0,
            scale(),
            &pal(),
            &SceneValues::new(),
            0,
            false,
            false,
        );
        assert_eq!(hits.len(), 1, "the chip keeps its region");
        // the `w: 0` region FILLES the auto stack, which measured 4 · 0.62 ·
        // 14 = 34.72 — a chip-sized target, not a 380 px row-wide one
        assert!(
            (hits[0].w - 34.72).abs() < 0.01,
            "region hugs the label, got {}",
            hits[0].w
        );
        assert!(
            (hits[0].x - 8.0).abs() < 0.01,
            "region starts at the -2 overhang, got {}",
            hits[0].x
        );
    }

    // ── the `Repeat` model (the bar's user-ordered center strip) ──
